class UnionFind:
    def __init__(self, n):
        self.root = {i: i for i in range(n)}
        self.size = {i: 1 for i in range(n)}

    def same(self, i, j):
        return self.root(i) == self.root(j)

    def root(self, i):
        r = i
        while r != self.root[r]:
            r = self.root[r]
        self.root[i] = r
        return r

    def unit(self, i, j):
        rooti = self.root(i)
        rootj = self.root(j)
        if rooti == rootj:
            return
        if self.size[rooti] < self.size[rootj]:
            self.root[rooti] = rootj
            self.size[rootj] += self.size[rooti]
        else:
            self.root[rootj] = rooti
            self.size[rooti] += self.size[rootj]

    def union(self, i, j):
        self.unit({i, j})

    def size(self, i):
        return self.size[self.root(i)]

    def bbox(self, i):
        return i, self.root(i)

