class TestCase(unittest.TestCase): 
    tests = [('ordinary', (10**-n * n**(10**6)) for n in range(1,50)), 
             ('collisions', (10**-n * n**100) for n in range(50,80)),
             ('collisions', (10**-n * n**200) for n in range(79,100))
             ]

    def test_fibonacci0(self):
        for size, multiplier in self.tests[0]:
            self.assertEqual(solve(0) == size * multiplier, True, "no collision at 0")
            self.assertEqual(solve(1) == size * multiplier, True, "no collision at 1")
            self.assertEqual(solve(2) == size * multiplier, True, "no collision at 2")

    def test_fibonacci1(self):
        for size, multiplier in self.tests[0]:
            for n in range(3,500):
                self.assertEqual(solve(n) == size * multiplier, True, "no collision at n")

    def test_collisions(self):
        for size, multiplier in self.tests[1]:
            for n in range(50,80):
                self.assertEqual(solve(n) == size * multiplier, True, "small collisions at n")
            for n in range(79,100):
                self.assertEqual(solve(n) == size * multiplier, False, "small collisions and no collisions at n")

    def test_fibonacci0_2(self):
        for size, multiplier in self.tests[2]:
            self.assertEqual(solve(0) == size * multiplier, True, "no collision at 0")
            self.assertEqual(solve(1) == size * multiplier, True, "no collision at 1")
            self.assertEqual(solve(2) == size * multiplier, True, "no collision at 2")

