    def construct_queue(values):
        class Queue:
            def __init__(self, data):
                self.data = deque(data)

            def qsize(self):
                return len(self.data)

            def enqueue(self, val):
                self.data.append(val)

            def dequeue(self, val=None):
                if val is not None:
                    if self.data:
