class Person:
    """A model for a person"""
    def __init__(self, name):
        self.name = name
        self.friends = set()
        self.is_known = False
    def knows(self, other_person):
        return self.friends.__contains__(other_person)
    def friend(self, other_person):
        self.friends.add(other_person)
        return other_person
    def __str__(self):
        return self.name


def print_friend_suggestions(people: [Person]) -> None:
    sorter = people.__sorted__(key=lambda p: len(p.friends), reverse=True)
    suggestion_list = sorter.__sorted__(key=lambda p: p.name)
    for (i, person) in enumerate(suggestion_list):
        print(f"{i+1} {person}")


class MyList:
    """A list for testing purposes"""
    def __init__(self, *items):
        self.__list = []
        for item in items:
            self.append(item)

    def append(self, item):
        self.__list.append(item)

    def __str__(self):
        output = ""
        if self.__list.__len__() > 0:
            output += "MyList["
            for i in range(self.__list.__len__()-1):
                output += str(self.__list[i]) + ", "
            output += str(self.__list[self.__list.__len__()-1]) + "]"
        else:
            output += "[]"
        return output

    def __sorted__(self, key=None):
        if key is None:
            output = self.__list.__sorted__()
        else:
            key_list = []
            for item in self.__list:
                key_list.append(key(item))
            output = self.__list.__sorted__(key=key_list.__key__())
        return output

    def __eq__(self, other_list):
        return self.items().__eq__(other_list)

